package walletspam

import (
	"encoding/hex"

	"github.com/xssnick/tonutils-go/tvm/cell"
)

// CodeHex is the current WalletSpam compiled BoC (Tolk), from jetton-prepaid/build/WalletSpam.json
// (base64 code_boc64 decoded to hex). Hash 1BFC588273D9DE92326658D6ADFC7762B322DD850E3EA84FC3D0B4AA04E3E193.
const CodeHex = ""

// JettonWalletCodeHex is the plain Tolk JettonWallet compiled BoC, from
// jetton-prepaid/build/JettonWallet.json (base64 code_boc64 decoded to hex).
// Hash D3825CE0109ECB6F6CD125B7A28258F488041153EB12E02C42045C4F05044573.
// The pool address depends on this code (each pool wallet owns a jetton wallet whose
// address is a pure state_init hash over {jettonBalance, owner, minter} with this code),
// so it must be known eagerly rather than fetched via get_jetton_data.
const JettonWalletCodeHex = ""

// LoadCode parses a WalletSpam BoC hex string into a *cell.Cell. Panics on bad input.
func LoadCode(codeHex string) *cell.Cell {
	bytes, err := hex.DecodeString(codeHex)
	if err != nil {
		panic("walletspam: decode code hex: " + err.Error())
	}
	c, err := cell.FromBOC(bytes)
	if err != nil {
		panic("walletspam: parse code BoC: " + err.Error())
	}
	return c
}

// LoadJettonWalletCode parses JettonWalletCodeHex into a *cell.Cell. Panics on bad input.
func LoadJettonWalletCode() *cell.Cell {
	return LoadCode(JettonWalletCodeHex)
}
